Median for our analytics dashboard. Happy with it. LGTM?

```js
function median(nums) {
  const sorted = [...nums].sort();
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}
```

This runs over about 50,000 log files every night. Approve?

```go
func countLines(paths []string) (int, error) {
	total := 0
	for _, p := range paths {
		f, err := os.Open(p)
		if err != nil {
			return 0, err
		}
		defer f.Close()
		n, err := lineCount(f)
		if err != nil {
			return 0, err
		}
		total += n
	}
	return total, nil
}
```

